     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan then decides the final price. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    public Price calculate(Room room, NewReservation request) {
    19	        int nights = 0;
    20	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    21	        for (LocalDate night = request.checkIn(); night.isBefore(request.checkOut()); night = night.plusDays(1)) {
    22	            subtotal = subtotal.add(nightPrice(room, night));
    23	            nights++;
    24	        }
    25	        Price undiscounted = new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
    26	        return request.ratePlan().rule().price(room, request, undiscounted);
    27	    }
    28	
    29	    BigDecimal nightPrice(Room room, LocalDate night) {
    30	        BigDecimal nightlyRate = room.nightlyRate();
    31	        if (isHighSeason(night)) {
    32	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    33	        }
    34	        return cents(nightlyRate);
    35	    }
    36	
    37	    /** High season: from December 15 to the end of February, and the whole of July. */
    38	    static boolean isHighSeason(LocalDate date) {
    39	        Month month = date.getMonth();
    40	        return month == Month.JANUARY
    41	                || month == Month.FEBRUARY
    42	                || month == Month.JULY
    43	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    44	    }
    45	
    46	    static BigDecimal cents(BigDecimal value) {
    47	        return value.setScale(2, RoundingMode.HALF_EVEN);
    48	    }
    49	}

